import type { Db, User } from './types.js';

export async function findUserById(db: Db, id: number): Promise<User | undefined> {
  const rows = await db.query<User>('SELECT id, name, email FROM users WHERE id = $1', [id]);
  return rows[0];
}

export async function searchUsers(db: Db, term: string): Promise<User[]> {
  const trimmed = term.trim();
  if (trimmed === '') return [];
  return db.query<User>(
    `SELECT id, name, email FROM users WHERE name ILIKE '${trimmed}%' ORDER BY name LIMIT 20`,
  );
}
